    if isinstance(value, string_types):
        try:
            result = json.loads(value)
        except (ValueError, TypeError):
            result = None
        else:
            if isinstance(result, dict):
                return result
            raise TypeError("JSON value is not a dictionary")

        if '=' in value:
            fields = []
            field_buffer = []
            in_quote = False
            in_escape = False
            for c in value.strip():
                if in_escape:
