                elif not in_quote and c in ('\'', '"'):
                    in_quote = c
                elif in_quote and in_quote == c:
                    in_quote = False
                elif not in_quote and c in (',', ' '):
                    field = ''.join(field_buffer)
                    if field:
                        fields.append(field)
                    field_buffer = []
                else:
                    field_buffer.append(c)

            field = ''.join(field_buffer)
            if field:
                fields.append(field)
            if in_quote or in_escape:
                raise TypeError("malformed key=value dictionary: unterminated quote or escape")
            pairs = []
            for field in fields:
                if '=' not in field:
                    raise TypeError("malformed key=value dictionary token %r: expected key=value" % field)
                key, item = field.split("=", 1)
                if not key or not item:
                    raise TypeError("malformed key=value dictionary token %r: key and value are required" % field)
                pairs.append((key, item))
            if not pairs:
                raise TypeError("dictionary requested, but no key=value pairs were found")
